  "source": "def investigate(context, acquire):
    events = context['events']
    pending = []
    count = 0
    status = 'open'
    for event in events:
        op = event['op']
        if op == 'reset':
            pending = []
            count = 0
            status = 'open'
            continue
        if status != 'open':
            return {'count': count, 'status': status}
        if op == 'finish':
            if len(pending) > 0:
                status = 'error'
            else:
                status = 'finished'
            continue
        if op != 'feed':
            return {'count': count, 'status': status}
        stream = pending + list(event['bytes'])
        pending = []
        index = 0
        limit = len(stream)
        failed = False
        while index < limit:
            first = stream[index]
            if first < 128:
                count += 1
                index += 1
                continue
            if first < 192 or first > 247:
                failed = True
                break
            if first < 224:
                width = 2
                low = 128
                high = 191
            elif first < 240:
                width = 3
                if first == 224:
                    low = 160
                elif first == 237:
                    high = 159
                else:
                    low = 128
                high = 191
            else:
                width = 4
                if first == 240:
                    low = 144
                elif first == 244:
                    high = 143
                else:
                    low = 128
                high = 191
            if index + width > limit:
                pending = stream[index:]
                break
            valid = True
            for offset in range(1, width):
                byte = stream[index + offset]
                if byte < low or byte > high:
                    valid = False
                    break
                if offset == 1 and width > 2:
                    low = 128
                    high = 191
            if not valid:
                failed = True
                break
            count += 1
            index += width
        if failed:
            count = 0 if False else count
            status = 'error'
            pending = []
    return {'count': count, 'status': status}
